1	import { NextResponse } from 'next/server';
2	
3	import { normalizeUnknownError, toHttpErrorResponse } from '@/lib/errors';
4	import { captureUnexpectedError } from '@/lib/observability/sentry';
5	
6	import { getPublicBaseUrl } from './urls';
7	
8	/**
9	 * Handles a GET request by invoking a service function and building a response.
10	 *
11	 * @template T - The type of the data returned by the service function.
12	 * @param serviceFunction - A function that processes the request parameters and returns a Promise
13	 *                          resolving to the data of type `T` or `null` if no data is found.
14	 * @param params - An object containing the request parameters as key-value pairs.
15	 * @param buildResponse - An optional function to build the response from the data. Defaults to `buildJsonResponse`.
16	 * @returns A Promise that resolves to a `NextResponse` object. If the service function returns `null`,
17	 *          a 404 response is returned. Otherwise, the response is built using the `buildResponse` function.
18	 */
19	export async function handleGET<T, S = T>(
20	    serviceFunction: ({ params }: { params: Record<string, string> }) => Promise<T | null>,
21	    { params }: { params: Record<string, string> },
22	    hooks?: {
23	        sanitize?: (data: T) => Promise<S>;
24	        buildResponse?: (data: S) => Promise<NextResponse>;
25	    },
26	): Promise<NextResponse> {
27	    try {
28	        // If no sanitize hook provided, pass data through (cast via unknown to satisfy TS when S != T)
29	        const sanitize: (data: T) => Promise<S> = hooks?.sanitize ?? (async (data: T) => await Promise.resolve(data as unknown as S));
30	        const buildResponse: (data: S) => Promise<NextResponse> = hooks?.buildResponse ?? buildJsonResponse;
31	
32	        const data = await serviceFunction({ params });
33	
34	        if (data == null) return new NextResponse('Not Found', { status: 404 });
35	
36	        const sanitizedData: S = await sanitize(data);
37	
38	        if (sanitizedData == null) return new NextResponse('Not Found', { status: 404 });
39	
40	        return buildResponse(sanitizedData);
41	    } catch (error) {
42	        const normalizedError = normalizeUnknownError(error);
43	        captureUnexpectedError(normalizedError, {
44	            layer: 'route',
45	            action: 'handleGET',
46	            extra: {
47	                params,
48	            },
49	        });
50	        const { status, message } = toHttpErrorResponse(normalizedError);
51	
52	        return new NextResponse(`Error: ${message}`, {
53	            status,
54	            headers: {
55	                'Content-Type': 'text/plain',
56	            },
57	        });
58	    }
59	}
60	
61	/**
62	 * Builds a JSON response with the provided data.
63	 *
64	 * @template T - The type of the data to include in the response.
65	 * @param data - The data to be serialized into JSON and included in the response body.
66	 * @returns A promise that resolves to a `NextResponse` object with the serialized JSON data,
67	 *          a status code of 200, and a `Content-Type` header set to `application/json`.
68	 */
69	async function buildJsonResponse<T>(data: T): Promise<NextResponse> {
70	    return Promise.resolve(NextResponse.json(data, {
71	        status: 200,
72	        headers: { 'Content-Type': 'application/json' },
73	    }));
74	}
75	
76	
77	/**
78	 * Builds a JSON error response for HTTP requests.
79	 *
80	 * Converts an error object into a standardized HTTP error response with
81	 * appropriate status code and JSON body containing the error message.
82	 *
83	 * @param error - The error object to convert. Can be any type.
84	 * @param fallbackMessage - The message to use if the error cannot be converted
85	 * to an HTTP response. Defaults to 'Internal Server Error'.
86	 * @returns A promise that resolves to a NextResponse with JSON-formatted error
87	 * details.
88	 */
89	export async function buildJsonErrorResponse(
90	    error: unknown,
91	    fallbackMessage = 'Internal Server Error',
92	): Promise<NextResponse> {
93	    const { status, message } = toHttpErrorResponse(error, fallbackMessage);
94	
95	    return Promise.resolve(NextResponse.json({ message }, {
96	        status,
97	        headers: { 'Content-Type': 'application/json' },
98	    }));
99	}
100	
101	/**
102	 * Builds a PNG response with the provided data.
103	 *
104	 * @param data - The Buffer to be converted into a PNG response.
105	 * @returns A promise that resolves to a `NextResponse` object with the data
106	 *          as a PNG and the appropriate headers.
107	 */
108	export async function buildPngResponse(data: Buffer): Promise<NextResponse> {
109	    return Promise.resolve(new NextResponse(new Uint8Array(data), {
110	        status: 200,
111	        headers: { 'Content-Type': 'image/png' },
112	    }));
113	}
114	
115	/**
116	 * Build a URL by resolving a base URI against the application's public base URL
117	 * and appending query parameters.
118	 *
119	 * To prevent open-redirect attacks, the resulting URL's origin must match the
120	 * application's public base URL. If the caller supplies an absolute URL whose
121	 * origin differs (e.g. `https://evil.com`), the path is discarded and the
122	 * application root (`/`) is used instead.
123	 *
124	 * @param baseUri - The base path or URL to resolve. Should be a relative path
125	 * (e.g. `/footy/response`). Absolute URLs pointing to a different origin are
126	 * treated as the root path.
127	 * @param params - An object whose keys and values will be appended as query
128	 * parameters. Multiple values for the same key will be appended (not replaced).
129	 * @returns A URL instance representing the resolved URL with the appended query
130	 * parameters.
131	 */
132	export function buildURLWithParams(baseUri: string, params: Record<string, string>) {
133	    const base = getPublicBaseUrl().toString();
134	    const url = new URL(baseUri, base);
135	    const expectedOrigin = new URL(base).origin;
136	
137	    // Prevent open redirects: if the resolved origin differs from our own,
138	    // fall back to the application root.
139	    if (url.origin !== expectedOrigin) {
140	        return buildURLWithParams('/', params);
141	    }
142	
143	    Object.entries(params).forEach(([key, value]) => {
144	        url.searchParams.append(key, value);
145	    });
146	
147	    return url;
148	}
