3	import { sendEmailVerification } from '@/actions/verifyEmail';
4	import {
5	    AuthError,
6	    ConflictError,
7	    NotFoundError,
8	    ValidationError,
9	} from '@/lib/errors';
10	import authService from '@/services/Auth';
11	import emailVerificationService from '@/services/EmailVerification';
12	import playerService from '@/services/Player';
13	import playerExtraEmailService from '@/services/PlayerExtraEmail';
14	
15	interface ClaimPlayerInvitationDeps {
16	    authService: Pick<typeof authService, 'getSessionUser' | 'updateCurrentUser'>;
17	    emailVerificationService: Pick<typeof emailVerificationService, 'getByToken' | 'markUsed'>;
18	    playerService: Pick<typeof playerService, 'getById' | 'update'>;
19	    playerExtraEmailService: Pick<typeof playerExtraEmailService, 'getAll' | 'getByEmail'>;
20	    sendEmailVerification: typeof sendEmailVerification;
21	}
22	
23	const defaultDeps: ClaimPlayerInvitationDeps = {
24	    authService,
25	    emailVerificationService,
26	    playerService,
27	    playerExtraEmailService,
28	    sendEmailVerification,
29	};
30	
31	/**
32	 * Retrieves and validates an invitation by its token.
33	 *
34	 * @param token - The invitation token to validate.
35	 * @param deps - The dependencies providing access to invitation and player
36	 * email services.
37	 * @returns The valid invitation object associated with the provided token.
38	 * @throws If the token is missing, the invitation is not found, expired,
39	 * already used, lacks a player reference, or the email is already associated
40	 * with a different player.
41	 */
42	async function getValidInvitation(token: string, deps: ClaimPlayerInvitationDeps) {
43	    if (!token) {
44	        throw new ValidationError('Missing invitation token.');
45	    }
46	
47	    const invitation = await deps.emailVerificationService.getByToken(token);
48	
49	    if (!invitation) {
50	        throw new NotFoundError('Invitation not found or expired.');
51	    }
52	
53	    if (invitation.usedAt) {
54	        throw new ConflictError('Invitation has already been used.');
55	    }
56	    if (invitation.expiresAt <= new Date()) {
57	        throw new ConflictError('Invitation has expired.');
58	    }
59	
60	    if (!invitation.playerId) {
61	        throw new ValidationError('Invitation is missing a player reference.');
62	    }
63	
64	    const existingExtraEmail = await deps.playerExtraEmailService.getByEmail(invitation.email);
65	    if (existingExtraEmail && existingExtraEmail.playerId !== invitation.playerId) {
66	        throw new ConflictError('Email address already belongs to another player.');
67	    }
68	
69	    return invitation;
70	}
71	
72	/**
73	 * Claims a player invitation using the provided token and returns essential
74	 * player information.
75	 *
76	 * Validates the invitation token, ensures the invitation includes a `playerId`,
77	 * retrieves the corresponding player, and returns a summary payload containing
78	 * the player's name, the invitation email, and the original token.
79	 *
80	 * @param token - The invitation token to validate and claim.
81	 * @param deps - Optional dependencies required for validation and data
82	 * retrieval. Defaults to `defaultDeps`.
83	 * @returns An object containing:
84	 * - `name`: The player's display name.
85	 * - `email`: The email address associated with the invitation.
86	 * - `token`: The original invitation token passed in.
87	 *
88	 * @throws {Error} If no player exists for the given `playerId`.
89	 * @throws {Error} Propagates errors from invitation validation (e.g., invalid
90	 * or expired token).
91	 */
92	export async function claimPlayerInvitationCore(
93	    token: string,
94	    deps: ClaimPlayerInvitationDeps = defaultDeps,
95	) {
96	    const invitation = await getValidInvitation(token, deps);
97	
98	    const player = await deps.playerService.getById(invitation.playerId!);
99	
100	    if (!player) {
101	        throw new NotFoundError('Player not found.');
102	    }
103	
104	    return {
105	        name: player.name,
106	        email: invitation.email,
107	        token,
108	    };
109	}
110	
111	/**
112	 * Finalizes the claim of a player invitation by linking the current user's
113	 * account to the player.
114	 *
115	 * This function performs the following operations:
116	 * 1. Validates the invitation token
117	 * 2. Verifies the session user exists and their email matches the invitation
118	 * 3. Ensures the user account is not already linked to a different player
119	 * 4. Links the current user to the player
120	 * 5. Updates the player with the account email
121	 * 6. Marks the invitation token as used
122	 * 7. Sends verification emails for any unverified extra emails associated with
123	 *    the player
124	 *
125	 * @param token - The invitation token to validate and process
126	 * @param deps - Optional dependencies object containing services for auth,
127	 * player management, email verification, and email sending. Uses default
128	 * dependencies if not provided.
129	 *
130	 * @throws {Error} If the invitation is invalid
131	 * @throws {Error} If no session user is found or the user email/ID is missing
132	 * @throws {Error} If the session user's email does not match the invitation
133	 * email
134	 * @throws {Error} If the session user account is already linked to a different
135	 * player
136	 *
137	 * @returns A promise that resolves when the invitation claim process is
138	 * complete
139	 */
140	export async function finalizePlayerInvitationClaimCore(
141	    token: string,
142	    deps: ClaimPlayerInvitationDeps = defaultDeps,
143	) {
144	    const invitation = await getValidInvitation(token, deps);
145	
146	    const sessionUser = await deps.authService.getSessionUser();
147	
148	    if (!sessionUser?.id || !sessionUser.email) {
149	        throw new AuthError('Login account not found for invitation.');
150	    }
151	
152	    if (sessionUser.email.toLowerCase() !== invitation.email.toLowerCase()) {
153	        throw new AuthError('Login account email does not match invitation.');
154	    }
155	
156	    if (sessionUser.playerId && sessionUser.playerId !== invitation.playerId) {
157	        throw new ConflictError('Login account is already linked to another player.');
158	    }
159	
160	    await deps.authService.updateCurrentUser({ playerId: invitation.playerId! });
161	    await deps.playerService.update({
162	        id: invitation.playerId!,
163	        accountEmail: invitation.email,
164	    });
165	    await deps.emailVerificationService.markUsed(token);
166	
167	    const extraEmails = await deps.playerExtraEmailService.getAll(invitation.playerId!);
168	    const unverifiedExtraEmails = extraEmails.filter((extraEmail) => !extraEmail.verifiedAt);
169	    const player = await deps.playerService.getById(invitation.playerId!);
170	
171	    await Promise.all(
172	        unverifiedExtraEmails.map((extraEmail) =>
173	            deps.sendEmailVerification(extraEmail.email, player ?? undefined),
174	        ),
175	    );
176	}
