3	import { ValidationError } from '@/lib/errors';
4	import { getPublicBaseUrl } from '@/lib/urls';
5	import { createVerificationToken } from '@/lib/verificationToken';
6	import emailVerificationService from '@/services/EmailVerification';
7	import playerService from '@/services/Player';
8	import type { CreatePlayerInput } from '@/types/actions/CreatePlayer';
9	
10	interface CreatePlayerDeps {
11	    playerService: Pick<typeof playerService, 'create'>;
12	    emailVerificationService: Pick<typeof emailVerificationService, 'create'>;
13	}
14	
15	const defaultDeps: CreatePlayerDeps = {
16	    playerService,
17	    emailVerificationService,
18	};
19	
20	/**
21	 * Generates a player invite verification token, optionally sends a verification
22	 * email, and returns a URL for the player to claim their invite.
23	 *
24	 * @param playerId - The unique identifier of the player to invite.
25	 * @param email - Optional email address to send the verification invite to.
26	 * @param deps - Optional dependencies for creating the player invite, defaults
27	 * to `defaultDeps`.
28	 * @returns A URL string for the player to verify and claim their invite.
29	 */
30	export async function addPlayerInviteCore(
31	    playerId: number,
32	    email?: string,
33	    deps: CreatePlayerDeps = defaultDeps,
34	) {
35	    const { token, expiresAt } = createVerificationToken();
36	
37	    if (email && email.length > 0) {
38	        await deps.emailVerificationService.create({
39	            playerId,
40	            email,
41	            token,
42	            expiresAt,
43	        });
44	    }
45	
46	    return new URL(
47	        `/api/footy/auth/verify/player-invite/${token}?redirect=/footy/auth/claim`,
48	        getPublicBaseUrl(),
49	    ).toString();
50	}
51	
52	/**
53	 * Creates a new player using the provided input data and dependencies.
54	 *
55	 * This function trims and validates the input fields, converts the introducer
56	 * to a number if present, and normalizes the email address. It then creates a
57	 * player record via the injected player service, and generates an invite link
58	 * for the newly created player.
59	 *
60	 * @param data - The input data required to create a player.
61	 * @param deps - Optional dependencies for player creation. Defaults to
62	 * `defaultDeps`.
63	 * @returns An object containing the created player and an invite link.
64	 * @throws {ValidationError} If the introducer is provided but is not a valid
65	 * number.
66	 */
67	export async function createPlayerCore(
68	    data: CreatePlayerInput,
69	    deps: CreatePlayerDeps = defaultDeps,
70	) {
71	    const name = data.name.trim();
72	    const introducedBy = data.introducedBy.trim();
73	    const introducedById = introducedBy ? Number(introducedBy) : null;
74	    const accountEmail = data.email?.trim() ? data.email.trim().toLowerCase() : null;
75	
76	    if (introducedBy && Number.isNaN(introducedById)) {
77	        throw new ValidationError('Introducer must be a number.');
78	    }
79	
80	    const player = await deps.playerService.create({
81	        name,
82	        introducedBy: introducedById,
83	        joined: new Date(),
84	        accountEmail,
85	    });
86	
87	    return {
88	        player,
89	        inviteLink: await addPlayerInviteCore(player.id, data.email, deps),
90	    };
91	}
