36	const ClaimSignupSchema = z.object({
37	    password: z.string().min(8, { message: 'Password must be at least 8 characters long' }),
38	    confirmPassword: z.string().min(1, { message: 'Please confirm your password' }),
39	}).refine((data) => data.password === data.confirmPassword, {
40	    message: 'Passwords do not match',
41	    path: ['confirmPassword'],
42	});
43	
44	export const ClaimSignup = ({ name, email, token }: Props) => {
45	    const [loading, setLoading] = useState(false);
46	    const [signupError, setSignupError] = useState<string | undefined>(undefined);
47	    const router = useRouter();
48	    const redirectPath = `/api/footy/auth/claim/${encodeURIComponent(token)}?redirect=/footy/profile`;
49	    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();
50	
51	    const form = useForm({
52	        initialValues: {
53	            password: '',
54	            confirmPassword: '',
55	        },
56	        validate: zod4Resolver(ClaimSignupSchema),
57	        validateInputOnBlur: true,
58	    });
59	
60	    const handleSignUp = async (values: z.infer<typeof ClaimSignupSchema>) => {
61	        setLoading(true);
62	        setSignupError(undefined);
63	
64	        try {
65	            await authClient.signUp.email({
66	                name: name,
67	                email: email,
68	                password: values.password,
69	            }, {
70	                onError: (ctx) => {
71	                    alert(ctx.error.message);
72	                },
73	            });
74	
75	            router.push(redirectPath);
76	        } catch (err) {
77	            captureUnexpectedError(err, {
78	                layer: 'client',
79	                action: 'signUpWithEmail',
80	                component: 'ClaimSignup',
81	                route: '/claim-signup',
82	                extra: {
83	                    redirectPath,
84	                },
85	            });
86	            setSignupError('Something went wrong. Please try again.');
87	        } finally {
88	            setLoading(false);
89	        }
90	    };
91	
92	    const validatedEmail = z.email().safeParse(email);
93	    const invitationError = !email || !name || !token || !validatedEmail.success ?
94	        'Missing or invalid invitation details.' : undefined;
95	
96	    if (invitationError) {
97	        return (
98	            <Container size="xs" mt="xl">
99	                <Stack>
100	                    <Notification
101	                        icon={<IconX size={config.notificationIconSize} />}
102	                        color="red"
103	                        withCloseButton={false}
104	                    >
105	                        {invitationError}
106	                    </Notification>
107	                    <Text ta="center">
108	                        <Anchor href="/footy">Return to the home page</Anchor>
109	                    </Text>
110	                </Stack>
111	            </Container>
112	        );
113	    }
114	
115	    const errorNotification = signupError ? (
116	        <Notification
117	            icon={<IconX size={config.notificationIconSize} />}
118	            color="red"
119	            onClose={() => setSignupError(undefined)}
120	        >
121	            {signupError}
122	        </Notification>
123	    ) : null;
124	
125	    return (
126	        <Container size="xs" mt="xl" >
127	            <Stack mb="lg">
128	                <Title order={2} mb="xs" w="100%" ta="center">
129	                    Finish creating your login
130	                </Title>
131	                <Text ta="center">
132	                    Your email address &quot;{email}&quot; has been verified. Choose how you want to sign in.
133	                </Text>
134	                <Divider mb="xs" />
135	                <Group justify="center" w="100%" mb="md">
136	                    <UnstyledButton
137	                        onClick={() => signInWithGoogle(socialRedirect)}
138	                        w="fit-content"
139	                        type="button"
140	                    >
141	                        <Image src="/google-signin-button-light.svg" alt="Sign in with Google" w={180} h={40} />
142	                    </UnstyledButton>
143	                    <UnstyledButton
144	                        onClick={() => signInWithMicrosoft(socialRedirect)}
145	                        w="fit-content"
146	                        type="button"
147	                    >
148	                        <Image src="/microsoft-signin-button-light.svg" alt="Sign in with Microsoft" w={215} h={41} />
149	                    </UnstyledButton>
150	                </Group>
151	                <Divider label="or" labelPosition="center" />
152	            </Stack>
153	
154	            <Box
155	                component="form"
156	                onSubmit={form.onSubmit(handleSignUp)}
157	            >
158	                <Stack>
159	                    <PasswordFields
