1	import 'server-only';
2	
3	import type { PlayerType } from 'prisma/zod/schemas/models/Player.schema';
4	
5	import { sendEmailCore } from '@/lib/core/sendEmail';
6	import {
7	    ConflictError,
8	    NotFoundError,
9	    ValidationError,
10	} from '@/lib/errors';
11	import { getPublicBaseUrl } from '@/lib/urls';
12	import { createVerificationToken } from '@/lib/verificationToken';
13	import emailVerificationService from '@/services/EmailVerification';
14	import playerExtraEmailService from '@/services/PlayerExtraEmail';
15	
16	interface VerifyEmailDeps {
17	    emailVerificationService: Pick<typeof emailVerificationService, 'create' | 'getByToken' | 'markUsed'>;
18	    playerExtraEmailService: Pick<typeof playerExtraEmailService, 'getByEmail' | 'upsert'>;
19	    sendEmailCore: typeof sendEmailCore;
20	}
21	
22	const defaultDeps: VerifyEmailDeps = {
23	    emailVerificationService,
24	    playerExtraEmailService,
25	    sendEmailCore,
26	};
27	
28	/**
29	 * Retrieves a valid email verification record by its token.
30	 *
31	 * Throws an error if:
32	 * - The token is missing.
33	 * - The verification record does not exist or is expired.
34	 * - The verification has already been used.
35	 * - The verification has expired.
36	 *
37	 * @param token - The email verification token to validate.
38	 * @param deps - The dependencies required for verification, including the email
39	 * verification service.
40	 * @returns The valid email verification record.
41	 * @throws {Error} If the token is missing, not found, expired, or already used.
42	 */
43	async function getValidVerification(token: string, deps: VerifyEmailDeps) {
44	    if (!token) {
45	        throw new ValidationError('Missing verification token.');
46	    }
47	
48	    const verification = await deps.emailVerificationService.getByToken(token);
49	
50	    if (!verification) {
51	        throw new NotFoundError('Verification not found or expired.');
52	    }
53	
54	    if (verification.usedAt) {
55	        throw new ConflictError('Verification has already been used.');
56	    }
57	    if (verification.expiresAt <= new Date()) {
58	        throw new ConflictError('Verification has expired.');
59	    }
60	
61	    return verification;
62	}
63	
64	/**
65	 * Requests email verification for a player's email address.
66	 *
67	 * This function normalizes and validates the provided email address, checks if
68	 * it belongs to the specified player, and ensures it has not already been
69	 * verified. If validation passes, it creates a verification token and stores
70	 * the verification request using the provided dependencies. Returns a
71	 * verification link for the user to complete the email verification process.
72	 *
73	 * @param email - The email address to verify.
74	 * @param playerId - The ID of the player associated with the email address, or
75	 * undefined if not applicable.
76	 * @param deps - The dependencies required for email and player verification
77	 * services.
78	 * @throws {Error} If the email address is missing, does not belong to the
79	 * player, or is already verified.
80	 * @returns An object containing the verification link for the email address.
81	 */
82	async function requestPlayerEmailVerification(
83	    email: string,
84	    playerId: number | undefined,
85	    deps: VerifyEmailDeps,
86	) {
87	    const normalizedEmail = email.trim();
88	
89	    /* v8 ignore next 3 */
90	    if (!normalizedEmail) {
91	        throw new ValidationError('Email address is required.');
92	    }
93	
94	    if (playerId !== undefined) {
95	        const existingEmail = await deps.playerExtraEmailService.getByEmail(normalizedEmail);
96	        if (existingEmail?.playerId !== playerId) {
97	            throw new ValidationError('Email address does not belong to this player.');
98	        }
99	
100	        if (existingEmail.verifiedAt) {
101	            throw new ConflictError('Email address is already verified.');
102	        }
103	    }
104	
105	    const { token, expiresAt } = createVerificationToken();
106	    await deps.emailVerificationService.create({
107	        playerId,
108	        email: normalizedEmail,
109	        token,
110	        expiresAt,
111	    });
112	
113	    return {
114	        verificationLink: new URL(
115	            `/api/footy/auth/verify/extra-email/${token}?redirect=${encodeURIComponent('/footy/profile')}`,
116	            getPublicBaseUrl(),
117	        ).toString(),
118	    };
119	}
120	
121	/**
122	 * Verifies an email address using a verification token.
123	 *
124	 * This function checks the validity of the provided token, ensures the email is
125	 * not already associated with another player, and marks the verification as
126	 * used. If successful, it associates the email with the player and returns
127	 * relevant information.
128	 *
129	 * @param token - The email verification token to validate.
130	 * @param deps - Optional dependencies required for verification. Defaults to
131	 * `defaultDeps`.
132	 * @returns An object containing the verified email, player ID, and verification
133	 * ID.
134	 * @throws If the verification is missing a player reference or if the email
135	 * address already belongs to another player.
136	 */
137	export async function verifyEmailCore(
138	    token: string,
139	    deps: VerifyEmailDeps = defaultDeps,
140	) {
141	    const verification = await getValidVerification(token, deps);
142	
143	    if (!verification.playerId) {
144	        throw new ValidationError('Verification is missing a player reference.');
145	    }
146	
147	    const existingEmail = await deps.playerExtraEmailService.getByEmail(verification.email);
148	    if (existingEmail && existingEmail.playerId !== verification.playerId) {
149	        throw new ConflictError('Email address already belongs to another player.');
150	    }
151	
152	    await deps.playerExtraEmailService.upsert(verification.playerId, verification.email, true);
153	    await deps.emailVerificationService.markUsed(token);
154	
155	    return {
156	        email: verification.email,
157	        playerId: verification.playerId?.toString(),
158	        verificationId: verification.id.toString(),
159	    };
160	}
161	
162	/**
163	 * Sends an email verification message to the specified email address.
164	 *
165	 * This function normalizes the email, requests a verification link, and sends
166	 * an email containing the link to the user. If a player is provided, their name
167	 * is included in the greeting.
168	 *
169	 * @param email - The email address to send the verification to.
170	 * @param player - Optional player information to personalize the email.
171	 * @param deps - Optional dependencies for email sending and verification link
172	 *               generation. Defaults to `defaultDeps` if not provided.
173	 * @returns A promise that resolves when the email has been sent, or returns
174	 * early if the email is empty.
175	 */
176	export async function sendEmailVerificationCore(
177	    email: string,
178	    player?: PlayerType,
179	    deps: VerifyEmailDeps = defaultDeps,
180	) {
181	    const normalizedEmail = email.trim();
182	
183	    if (!normalizedEmail) {
184	        return;
185	    }
186	
187	    const { verificationLink } = await requestPlayerEmailVerification(
188	        normalizedEmail,
189	        player?.id,
190	        deps,
191	    );
192	
193	    const html = [
194	        `<p>Hello${player?.name ? ` ${player.name}` : ''},</p>`,
195	        '<p>Please verify your email address by clicking the link below:</p>',
196	        `<p><a href="${verificationLink}">Verify your email</a></p>`,
197	        '<p>If you did not request this, you can ignore this message.</p>',
198	    ].join('');
199	
200	    await deps.sendEmailCore({
201	        to: normalizedEmail,
202	        subject: 'Verify your email address',
203	        html,
204	    });
205	}
