93	 * @param token - The unique token identifying the contact enquiry.
94	 * @param deps - Optional dependencies required for delivering the enquiry.
95	 * Defaults to `defaultDeps`.
96	 * @returns An object indicating the result of the operation:
97	 *   - `{ enquiry: 'already-delivered' }` if the enquiry has already been
98	 *     delivered.
99	 *   - `{ enquiry: 'verified' }` if the enquiry was successfully delivered and
100	 *     verified.
101	 * @throws {NotFoundError} If the enquiry cannot be found for the provided token.
102	 */
103	export async function deliverContactEnquiryCore(
104	    token: string,
105	    deps: SendEnquiryDeps = defaultDeps,
106	) {
107	    const enquiry = await deps.contactEnquiryService.getByToken(token);
108	
109	    if (!enquiry) {
110	        throw new NotFoundError('Enquiry not found for this verification.');
111	    }
112	
113	    if (enquiry.deliveredAt) {
114	        return { enquiry: 'already-delivered' } as const;
115	    }
116	
117	    const formattedMessage = formatMessage(enquiry.message);
118	    const subject = `Enquiry from ${enquiry.name}`;
119	
120	    const html = [
121	        '<p>New enquiry received:</p>',
122	        `<p><strong>Name:</strong> ${enquiry.name}</p>`,
123	        `<p><strong>Email:</strong> <a href="mailto:${enquiry.email}">${enquiry.email}</a></p>`,
124	        `<p><strong>Message:</strong><br />${formattedMessage || '-'}</p>`,
125	    ].join('');
126	
127	    await deps.sendEmailCore({
128	        to: config.contactEmailDestination,
129	        subject,
130	        html,
131	    });
