12	export const GET = async (request: NextRequest, props: { params: Promise<Record<string, string>> }) => {
13	    const { purpose, token } = await props.params;
14	    const searchParams = request.nextUrl.searchParams;
15	    const redirectParam = searchParams.get('redirect') ?? '/';
16	    let redirect: URL;
17	
18	    try {
19	        let data = {};
20	
21	        switch (purpose) {
22	            case 'player-invite':
23	                data = await claimPlayerInvitation(token);
24	                break;
25	            case 'extra-email':
26	                data = await verifyEmail(token);
27	                break;
28	            case 'enquiry':
29	                data = await deliverContactEnquiry(token);
30	                break;
31	            default:
32	                throw new ValidationError(
33	                    `Invalid verification purpose "${purpose}". Must be one of: player-invite, extra-email, enquiry.`,
34	                );
35	        }
36	
37	        redirect = buildURLWithParams(redirectParam, data);
38	    } catch (error) {
39	        captureUnexpectedError(error, {
40	            layer: 'route',
41	            action: 'verifyAuthToken',
42	            route: '/api/footy/auth/verify/[purpose]/[token]',
43	            tags: {
44	                purpose,
45	            },
46	            extra: {
47	                redirectParam,
48	            },
49	        });
50	        const { message: errorMessage } = toHttpErrorResponse(error, 'Unable to verify email.');
51	
52	        redirect = buildURLWithParams(redirectParam, { error: errorMessage });
53	    }
54	
55	    return NextResponse.redirect(redirect);
56	};
