import { Anchor, Notification, Paper, Stack, Text } from '@mantine/core';
import { IconX } from '@tabler/icons-react';
import { ReactNode } from 'react';

import { claimPlayerInvitation } from '@/actions/claimPlayerInvitation';
import { ClaimSignup } from '@/components/ClaimSignup/ClaimSignup';
import { config } from '@/lib/config';
import { toPublicMessage } from '@/lib/errors';
import { captureUnexpectedError } from '@/lib/observability/sentry';

interface PageProps {
    params: Promise<{ token: string }>;
}

export const metadata = { title: 'Sign Up' };

// TODO: Work out whether things like this <Paper> should be in the page or
// in the component. This will probably best be done when I work on using
// <Container> where appropriate, and then I can see if it makes sense to
// have the <Paper> in the page or in the component.

const Page = async ({ params }: PageProps) => {
    const { token } = await params;
    let content: ReactNode;

    try {
        const { name, email } = await claimPlayerInvitation(token);

        content = <ClaimSignup name={name} email={email} token={token} />;
    } catch (error) {
        captureUnexpectedError(error, {
            layer: 'server',
            action: 'claimPlayerInvitation',
            component: 'ClaimSignup',
            route: '/footy/auth/claim/[token]',
        });

        content = (
            <Stack>
                <Notification
                    icon={<IconX size={config.notificationIconSize} />}
                    color="red"
                    withCloseButton={false}
                >
                    {toPublicMessage(error, 'This invitation link is invalid.')}
                </Notification>
                <Text ta="center">
                    <Anchor href="/footy">Return to the home page</Anchor>
                </Text>
            </Stack>
        );
    }

    return (
        <Paper w="100%" maw="35rem" p="xl">
            {content}
        </Paper>
    );
};

export default Page;

import { render, screen } from '@testing-library/react';
import { vi } from 'vitest';

const { claimPlayerInvitationMock, captureUnexpectedErrorMock } = vi.hoisted(() => ({
    claimPlayerInvitationMock: vi.fn(),
    captureUnexpectedErrorMock: vi.fn(),
}));

vi.mock('@/actions/claimPlayerInvitation', () => ({
    claimPlayerInvitation: claimPlayerInvitationMock,
}));

vi.mock('@/lib/observability/sentry', () => ({
    captureUnexpectedError: captureUnexpectedErrorMock,
}));

vi.mock('@/components/ClaimSignup/ClaimSignup', () => ({
    ClaimSignup: vi.fn(({ name, email, token }: { name: string; email: string; token: string }) => (
        <div>ClaimSignup: {name} / {email} / {token}</div>
    )),
}));

import { ValidationError } from '@/lib/errors';

import Page from './page';

describe('Claim Sign Up page', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('looks up the invitation and renders ClaimSignup with the resolved details', async () => {
        claimPlayerInvitationMock.mockResolvedValue({ name: 'Alice', email: 'alice@example.com' });

        const element = await Page({ params: Promise.resolve({ token: 'tok' }) });
        render(element);

        expect(claimPlayerInvitationMock).toHaveBeenCalledWith('tok');
        expect(screen.getByText('ClaimSignup: Alice / alice@example.com / tok')).toBeInTheDocument();
        expect(captureUnexpectedErrorMock).not.toHaveBeenCalled();
    });

    it('shows the public error message and does not render ClaimSignup when the invitation is invalid', async () => {
        claimPlayerInvitationMock.mockRejectedValue(
            new ValidationError('Invitation is missing a player reference.', {
                publicMessage: 'This invitation link is invalid.',
            }),
        );

        const element = await Page({ params: Promise.resolve({ token: 'bad-tok' }) });
        render(element);

        expect(screen.getByText('This invitation link is invalid.')).toBeInTheDocument();
        expect(screen.queryByText(/ClaimSignup:/)).not.toBeInTheDocument();
        expect(screen.getByRole('link', { name: /Return to the home page/i })).toHaveAttribute('href', '/footy');
    });

